import React from 'react';
import { motion } from 'framer-motion';

const Portfolio = () => {
  const projects = [
    {
      title: 'Analytics Dashboard',
      description: 'A comprehensive data visualization dashboard built for a fintech startup. Features real-time data updates and custom reporting tools.',
      image: 'https://lh3.googleusercontent.com/aida-public/AB6AXuBCoOXCpXaeuvSaA07TEWcqQTL6fy8k3BM_F6naquYmtpAYVF1vfGImDWUOToL8RGm5JXUx7FSHaJpbrZ1HhPE1j1AbW0P2WCWd5570TQPynGrU33AYS3C43Z9NO4EGbu-c2tMyN-bFmPYAA7S0N6fbZ3BPhKmkjYZfgV72TFPHQnB2T2k_ksozX6iGPyRDCkfpDzlz36Q-DQbIp7DNYvsKeFLZriC7Q-N-xGNn7QfzghupBMn9Aho-Apue5dF9Phf2lPp6ifk3qQ0',
      tags: ['React', 'D3.js', 'Sass']
    },
    {
      title: 'E-commerce Platform',
      description: 'A fully responsive online store developed for a fashion brand. Includes stripe integration, inventory management, and a custom CMS.',
      image: 'https://lh3.googleusercontent.com/aida-public/AB6AXuAe-_1SMdZVKW0DArkMujFkO9Hd8XZcTH4nJrVvz_HhGhSxOGnJxxVo28GiaIS9jX5U_pA9RYR0Slk63c5ca97yPfjoCRoNyQxOHyPrG7XkgzKVbdcZknpNpcnXBnOnpqhseEwvxif_XF7NUcV9VjbzWEJ8tBPkiRIT571B1dJ7n8-v0nl5cujdxCTVJQRltUuhtFcEQbS6p_Ex-ZlmQ1fIBWIHo7brD53DXxpB4UwQcL2fJbBxeb_hxBoyJtiisvrAPq_rbA1temU',
      tags: ['Vue.js', 'Node.js', 'MongoDB']
    },
    {
      title: 'Task Management App',
      description: 'A productivity application designed for remote teams. Features include drag-and-drop boards, time tracking, and team chat.',
      image: 'https://lh3.googleusercontent.com/aida-public/AB6AXuAfMQJunVxp2sFddprbUMhhg5f3igz8h8vR8A1g9YkpEnAucwKVHo5OMBzIytcDYkatqj_iV8NLDLLXf1Lq4vn3e9KN_qi1eiL58RwSk2LO5HA0n6lCGvXuWMcSOBywtayi5V7gs8-oMOm4okNeFg1FM_nr3bOnm5oLfnKzBEh8Y889twpIxg847AOs07OGk8gDziUxRfkO6VdnJVQW23EblLwW9vjUO33-htLIEpiDiJQfbUdVJJtXG6awjr3C1zljYq0tX-g-TOY',
      tags: ['Angular', 'Firebase', 'TypeScript']
    },
    {
      title: 'Healthcare Portal',
      description: 'Secure patient portal allowing appointment scheduling, medical record access, and secure messaging with doctors.',
      image: 'https://lh3.googleusercontent.com/aida-public/AB6AXuDpJv_oal1VZKbkwrxFEU0hWbx82OIN1Iy7y7Pdo29Wqj1qRo1cLm_su37Xe_wPpkfNXcxCDyDFfnjXOIkkFA8xySP2f-6f9asf8o1kLYRjaRlmaSx6tm4XugiLcbT-WA-gCH-jz_F-psIMj6H0Zt0T22siUGOdk6sfhNsjuRJEZchL-RJbj6YiuWl04FFZroR_UpFqpyRIRxDPOBdoI2wq17zQq7ZXHCPUDD5stq8nka85VH5uUU0EiPKa3bNE37dc5eU-IjMkAkE',
      tags: ['Python', 'Django', 'PostgreSQL']
    },
    {
      title: 'Travel Booking App',
      description: 'A mobile-first web application for booking flights and hotels. Integrates with multiple travel APIs for best price comparison.',
      image: 'https://lh3.googleusercontent.com/aida-public/AB6AXuAQIutyUOjk-OKMyrO17cKXgobcUKU8wYzna3jNLRhx40SL9efKwB6ttNKfwT8Z0QjLRi1Sym-p-0LfGIdtDiq6V7aBaB64XMuhpW2DBpZzLE05bUxlsssHrhbw-Ce-O9-9avF7ITiVJxSbDz4iVVVxX9pMk7IB8CAExtJd5x-DbZ1lIZtYUtg9vif7107LapM2rGqOIK6cR1cROaZV9pXCLhZ7yNiBV36jeHpb2KF53L4zUW88jCLenMjW6aguHkIMZQ3_ZvGXbIo',
      tags: ['React Native', 'Redux', 'API']
    },
    {
      title: 'Code Learning Platform',
      description: 'An interactive platform for learning programming languages. Includes code editors, quizzes, and progress tracking.',
      image: 'https://lh3.googleusercontent.com/aida-public/AB6AXuAGrwglcen0b0M7ZyUoEq5uMa9st7OvkR1vNfJpn3UxN0v5IfPykzfDOh54TJ6NrJ3UAsgFzLkYuIfWlxc3Lbxyg-vEVx6cccuF26yIGrvojUu5PYABP_AzAdONZn4jjINNSVsYRmo7Niw-ip5f6tpV-r3vBvGi1bf4-EeiHzPiDbE8qc-6vUKLm91FqkHrFMhy82ioaPXtvfNB-6skOoGbrjcPpM4lCuIy07brPu-ARLRi-IBjNnOhLeapD7Bq-tIDcB_i6KMQNro',
      tags: ['Next.js', 'Tailwind', 'Prisma']
    }
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.6
      }
    }
  };

  return (
    <motion.section
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, amount: 0.1 }}
      variants={containerVariants}
      className="mb-20"
    >
      <motion.header variants={itemVariants} className="mb-12">
        <motion.h1
          whileHover={{ scale: 1.02 }}
          className="text-4xl md:text-5xl font-black text-gray-900 dark:text-white mb-6 relative inline-block"
        >
          My Portfolio
          <span className="absolute bottom-1 left-0 w-full h-3 bg-primary/30 -z-10"></span>
        </motion.h1>
        <p className="text-lg leading-relaxed text-gray-600 dark:text-gray-300 max-w-3xl">
          Welcome to my online portfolio. Lorem ipsum dolor sit amet, consectetuer adipiscing elit. Aenean commodo ligula eget dolor. I'm taking on freelance work at the moment. Want some help building your software?
        </p>
      </motion.header>

      <motion.div
        variants={containerVariants}
        className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8"
      >
        {projects.map((project, index) => (
          <motion.article
            key={index}
            variants={itemVariants}
            whileHover={{ y: -10, scale: 1.02 }}
            className="bg-white dark:bg-surface-dark rounded-lg overflow-hidden shadow-md hover:shadow-xl transition-shadow duration-300 flex flex-col group"
          >
            <div className="relative overflow-hidden aspect-video">
              <motion.img
                whileHover={{ scale: 1.1 }}
                transition={{ duration: 0.5 }}
                alt={`Project Screenshot - ${project.title}`}
                className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                src={project.image}
              />
              <motion.div
                initial={{ opacity: 0 }}
                whileHover={{ opacity: 1 }}
                transition={{ duration: 0.3 }}
                className="absolute inset-0 bg-primary/80 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center"
              >
                <motion.a
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  className="text-white border-2 border-white font-bold py-2 px-6 rounded-full hover:bg-white hover:text-primary transition-colors"
                  href="#"
                >
                  <i className="fas fa-eye mr-2"></i> View Case Study
                </motion.a>
              </motion.div>
            </div>
            <div className="p-6 flex flex-col flex-1">
              <motion.h3
                whileHover={{ color: '#54B689' }}
                className="text-xl font-bold text-gray-900 dark:text-white mb-2 group-hover:text-primary transition-colors"
              >
                {project.title}
              </motion.h3>
              <p className="text-gray-600 dark:text-gray-400 text-sm mb-4 flex-1">
                {project.description}
              </p>
              <div className="flex flex-wrap gap-2 mb-4">
                {project.tags.map((tag, tagIndex) => (
                  <motion.span
                    key={tagIndex}
                    whileHover={{ scale: 1.05 }}
                    className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 text-xs px-2 py-1 rounded"
                  >
                    {tag}
                  </motion.span>
                ))}
              </div>
              <motion.a
                whileHover={{ x: 5 }}
                className="text-primary hover:text-primary-dark font-medium text-sm flex items-center mt-auto"
                href="#"
              >
                View Project{' '}
                <motion.i
                  whileHover={{ x: 3 }}
                  className="fas fa-arrow-right ml-2 text-xs transition-transform group-hover:translate-x-1"
                ></motion.i>
              </motion.a>
            </div>
          </motion.article>
        ))}
      </motion.div>
    </motion.section>
  );
};

export default Portfolio;
